-- Fixed, bounded review approval. No credential reads and no Pin dispatch.
begin;
set local statement_timeout='20s';
set local lock_timeout='5s';
select pg_advisory_xact_lock(1617125,13);
create temporary table reviewed_input as select * from jsonb_to_recordset($data$[{"queue_id":"fc3d20af-4b91-4ddd-8c33-50feb8204cd9","shop":"KoltCraftStudio","listing_id":"1762833875","source_url":"https://www.etsy.com/listing/1762833875/wide-shoulder-solid-wood-suit-hangers","category":"Wooden Hangers","image_url":null,"destination_url":"https://www.etsy.com/listing/1762833875/wide-shoulder-solid-wood-suit-hangers","title":"Wide Shoulder Solid Wood Suit Hangers With Swivel Hook","body":"Wide Shoulder Solid Wood Suit Hangers With Swivel Hook Style: classic. Materials: wood. View details and available options on Etsy.","handle":"sailing_981","mapped":true,"history_count":0,"review_exists":false,"account":"P2","board_id":"863494997243989843","board_name":"storage","visual_verified":true,"available":true,"checked_at":"2026-10-16T02:10:55.067Z","new_title":"Wide-Shoulder Wooden Suit Hangers","new_body":"Dark wood grain and broad curved shoulders bring a coordinated look to your wardrobe. These KoltCraftStudio hangers feature silver-tone swivel hooks. See the original Etsy listing for sizes and quantity options.","new_image_url":"https://i.etsystatic.com/43671795/r/il/210f91/8162090335/il_794xN.8162090335_k1e4.jpg","facebook_draft":"A coordinated closet starts with the details. These dark wooden hangers from KoltCraftStudio combine wide curved shoulders with silver-tone swivel hooks. Check the listing for sizes and quantities. https://www.etsy.com/listing/1762833875/wide-shoulder-solid-wood-suit-hangers","unresolved_reason":null},{"queue_id":"1a1dad3b-7b9b-487f-9f78-06b3632146d7","shop":"KoltCraftStudio","listing_id":"1776683908","source_url":"https://www.etsy.com/listing/1776683908/wide-shoulder-camphor-wood-suit-hangers","category":"Wooden Hangers","image_url":null,"destination_url":"https://www.etsy.com/listing/1776683908/wide-shoulder-camphor-wood-suit-hangers","title":"Wide Shoulder Camphor Wood Suit Hangers: 360 Swivel Hook","body":"Wide Shoulder Camphor Wood Suit Hangers: 360 Swivel Hook Style: classic, luxury. Materials: camphor_wood. View details and available options on Etsy.","handle":"sailing_981","mapped":true,"history_count":0,"review_exists":false,"account":"P2","board_id":"863494997243989843","board_name":"storage","visual_verified":true,"available":true,"checked_at":"2026-10-16T02:10:55.067Z","new_title":"Camphor Wood Hangers with Swivel Hooks","new_body":"Light camphor wood, broad shoulders and gold-tone hooks create a warm wardrobe accent. A lower bar offers space for folded accessories. From KoltCraftStudio; see Etsy for current quantity options.","new_image_url":"https://i.etsystatic.com/43671795/r/il/6bef8e/6257386850/il_794xN.6257386850_m0og.jpg","facebook_draft":"Light wood and gold-tone hooks add a warm touch to closet organization. Explore these wide-shoulder camphor wood hangers from KoltCraftStudio, with lower bars for folded accessories. https://www.etsy.com/listing/1776683908/wide-shoulder-camphor-wood-suit-hangers","unresolved_reason":null},{"queue_id":"5069aba6-9aa2-444e-98c8-7e71c927a367","shop":"WOGOL","listing_id":"4438724155","source_url":"https://www.etsy.com/listing/4438724155/linen-striped-curtains-with-valance","category":"Linen Curtains","image_url":null,"destination_url":"https://www.etsy.com/listing/4438724155/linen-striped-curtains-with-valance","title":"Linen Striped Curtains with Valance, Farmhouse Blue Stripe Light Filtering Window Drapes","body":"Linen Striped Curtains with Valance, Farmhouse Blue Stripe Light Filtering Window Drapes Style: striped, farmhouse. Materials: linen, cotton. View details and available options on Etsy.","handle":"icyndizhang","mapped":true,"history_count":0,"review_exists":false,"account":"P1","board_id":"801218658646993070","board_name":"CyndiZhangStudio","visual_verified":true,"available":true,"checked_at":"2026-10-16T02:11:14.987Z","new_title":"Blue Striped Curtains with a Soft Valance","new_body":"Fine blue stripes and a softly gathered valance bring relaxed farmhouse character to these WOGOL curtains. Choose the heading style, size and panel quantity on the original Etsy listing.","new_image_url":"https://i.etsystatic.com/45174159/r/il/c7d795/7634559899/il_794xN.7634559899_fbyj.jpg","facebook_draft":"Bring a soft striped accent to your window. WOGOL offers this valance curtain in several heading styles, sizes and panel quantities. Choose the option that fits your room. https://www.etsy.com/listing/4438724155/linen-striped-curtains-with-valance","unresolved_reason":null}]$data$::jsonb) as x(queue_id uuid,shop text,listing_id text,source_url text,category text,image_url text,destination_url text,title text,body text,handle text,board_id text,new_title text,new_body text,checked_at timestamptz,new_image_url text,facebook_draft text);
select q.id from publish_queue q join reviewed_input x on x.queue_id=q.id for update of q;
select cv.id from content_variants cv join publish_queue q on q.content_variant_id=cv.id join reviewed_input x on x.queue_id=q.id for update of cv;
select p.id from products p join publish_queue q on q.product_id=p.id join reviewed_input x on x.queue_id=q.id for update of p;
do $$
begin
 if not exists(select 1 from pinterest_publish_settings where singleton and enabled and access_tier='standard') then raise exception 'Enabled Standard settings required'; end if;
 if exists(select 1 from reviewed_input where checked_at < now()-interval '24 hours' or checked_at>now()) then raise exception 'Fixed approval expired'; end if;
 if (select count(*) from reviewed_input x join publish_queue q on q.id=x.queue_id join products p on p.id=q.product_id and p.shop_id=q.shop_id join shops s on s.id=q.shop_id join content_variants cv on cv.id=q.content_variant_id and cv.product_id=p.id and cv.shop_id=s.id join social_accounts a on a.id=q.social_account_id
 where q.platform='pinterest' and cv.platform='pinterest' and q.status='draft' and cv.status='draft' and s.status='active' and a.active and a.handle=x.handle and a.platform='pinterest' and s.shop_name=x.shop and p.etsy_listing_id=x.listing_id and p.etsy_url=x.source_url and cv.destination_url=x.destination_url and cv.board_or_category=x.category and cv.image_url is not distinct from x.image_url and cv.title=x.title and cv.body=x.body
 and exists(select 1 from shop_social_accounts m where m.shop_id=s.id and m.social_account_id=a.id and m.platform='pinterest' and m.active)
 and exists(select 1 from pinterest_oauth_credentials cr where cr.social_account_id=a.id and lower(cr.pinterest_username)=lower(a.handle))
 and not exists(select 1 from publish_history h where h.product_id=p.id)
 and not exists(select 1 from pinterest_publish_attempts pa where pa.queue_id=q.id)) <> 3 then raise exception 'Expected 3 unchanged, mapped, unattempted drafts'; end if;
 if exists(select 1 from pinterest_publish_reviews rev join reviewed_input x on rev.queue_id=x.queue_id where rev.board_id<>x.board_id or rev.snapshot<>pinterest_publish_snapshot(x.queue_id)) then raise exception 'Existing review differs'; end if;
end $$;
update products p set listing_status='active',last_seen_at=x.checked_at from publish_queue q join reviewed_input x on x.queue_id=q.id where p.id=q.product_id;
update content_variants cv set status=case when x.board_id is null then 'draft'::content_status else 'ready'::content_status end,title=x.new_title,body=x.new_body,image_url=x.new_image_url from publish_queue q join reviewed_input x on x.queue_id=q.id where cv.id=q.content_variant_id;

update products p set primary_image_url=x.new_image_url,original_image_urls=jsonb_build_array(x.new_image_url),source_payload=coalesce(p.source_payload,'{}'::jsonb)||jsonb_build_object('material_verification',jsonb_build_object('source_url',x.source_url,'verified_at',x.checked_at,'image_verified',true,'batch','daily-20261016')) from publish_queue q join reviewed_input x on x.queue_id=q.id where p.id=q.product_id;
update content_variants cv set image_url=x.new_image_url,title=x.new_title,body=x.facebook_draft
from publish_queue q join reviewed_input x on x.queue_id=q.id where cv.product_id=q.product_id and cv.shop_id=q.shop_id and cv.platform='facebook' and cv.status='draft'
and not exists(select 1 from publish_history h where h.content_variant_id=cv.id)
and not exists(select 1 from publish_queue fq where fq.content_variant_id=cv.id and fq.status<>'draft');

insert into pinterest_publish_reviews(queue_id,board_id,snapshot,listing_checked_at,source_url)
select x.queue_id,x.board_id,pinterest_publish_snapshot(x.queue_id),x.checked_at,x.source_url from reviewed_input x where x.board_id is not null on conflict(queue_id) do nothing;
update publish_queue q set status='ready',updated_at=now() from reviewed_input x where q.id=x.queue_id and q.status='draft' and x.board_id is not null;
select json_build_object('queue_id',q.id,'status',q.status,'board_id',rev.board_id,'snapshot_matches',rev.snapshot=pinterest_publish_snapshot(q.id),'listing_checked_at',rev.listing_checked_at) from publish_queue q join reviewed_input x on x.queue_id=q.id left join pinterest_publish_reviews rev on rev.queue_id=q.id;
select json_build_object('public_publish_enabled',enabled) from pinterest_publish_settings where singleton;

create temporary table batch_input as select * from jsonb_to_recordset($data$[{"account":"P4","shop":"QuGifts","listing_id":"4549033180","source_url":"https://www.etsy.com/listing/4549033180/shell-wall-hanging-macrame-coastal-decor","category":"Wall Decor","handle":"cindyzhang62","board_id":"675399344056772225","board_name":"Decor","visual_verified":true,"available":true,"checked_at":"2026-10-16T02:11:57.756Z","new_title":"Shell and Macrame Wall Hanging","new_body":"Cream macrame knots and cascading shell discs add soft texture to a coastal-inspired wall. This QuGifts hanging has a wooden dowel and bead details. See the original Etsy listing for size options.","new_image_url":"https://i.etsystatic.com/38006525/r/il/21eaa8/8381007735/il_794xN.8381007735_knnc.jpg","facebook_draft":"A coastal detail for a quiet corner: this QuGifts wall hanging combines cream macrame, shell discs and wooden beads. See the available sizes in the original shop. https://www.etsy.com/listing/4549033180/shell-wall-hanging-macrame-coastal-decor","unresolved_reason":null,"body":"Cream macrame knots and cascading shell discs add soft texture to a coastal-inspired wall. This QuGifts hanging has a wooden dowel and bead details. See the original Etsy listing for size options.","image_url":"https://i.etsystatic.com/38006525/r/il/21eaa8/8381007735/il_794xN.8381007735_knnc.jpg"},{"account":"P5","shop":"NinaJiaStudio","listing_id":"4477926256","source_url":"https://www.etsy.com/listing/4477926256/new-chinese-cranewave-jacquard","category":"Shoulder Bags","handle":"ivy5205","board_id":"713820678377803445","board_name":"Fashion","visual_verified":true,"available":true,"checked_at":"2026-10-16T02:12:32.647Z","new_title":"Crane and Wave Jacquard Tote Bag","new_body":"A cream-toned jacquard tote with flying cranes, subtle wave motifs and long shoulder straps. This NinaJiaStudio bag has a magnetic-snap closure. Explore the original Etsy listing for details.","new_image_url":"https://i.etsystatic.com/61131894/r/il/c54e62/8531347571/il_794xN.8531347571_7hng.jpg","facebook_draft":"An understated pattern for an everyday outfit: this cream-toned NinaJiaStudio tote pairs crane and wave motifs with long shoulder straps and a magnetic snap. https://www.etsy.com/listing/4477926256/new-chinese-cranewave-jacquard","unresolved_reason":null,"body":"A cream-toned jacquard tote with flying cranes, subtle wave motifs and long shoulder straps. This NinaJiaStudio bag has a magnetic-snap closure. Explore the original Etsy listing for details.","image_url":"https://i.etsystatic.com/61131894/r/il/c54e62/8531347571/il_794xN.8531347571_7hng.jpg"}]$data$::jsonb) x(shop text,listing_id text,source_url text,category text,board_id text,new_title text,body text,image_url text,checked_at timestamptz,facebook_draft text,handle text);
do $$ begin
 if not exists(select 1 from pinterest_publish_settings where singleton and enabled and access_tier='standard') then raise exception 'Enabled Standard required'; end if;
 if exists(select 1 from batch_input where checked_at<now()-interval '24 hours' or checked_at>now()) then raise exception 'Verification expired'; end if;
 if (select count(*) from batch_input x join shops s on s.shop_name=x.shop and s.status='active' join shop_social_accounts m on m.shop_id=s.id and m.active and m.platform='pinterest' join social_accounts a on a.id=m.social_account_id and a.handle=x.handle and a.active and a.platform='pinterest' join pinterest_oauth_credentials cr on cr.social_account_id=a.id and lower(cr.pinterest_username)=x.handle)<>2 then raise exception 'Batch routing or authorization changed'; end if;
end $$;
-- Report prior records before inserting; only genuinely new products enter this batch.
select json_build_object('preexisting_listing',p.etsy_listing_id,'history_count',(select count(*) from publish_history h where h.product_id=p.id)) from products p join batch_input x on x.listing_id=p.etsy_listing_id;
create temporary table new_products(id uuid,shop_id uuid,etsy_listing_id text);
with ins as (
 insert into products(shop_id,etsy_listing_id,etsy_url,title,category,listing_status,primary_image_url,original_image_urls,source_payload,source_discovered_at,last_seen_at)
 select s.id,x.listing_id,x.source_url,x.new_title,x.category,'active',x.image_url,jsonb_build_array(x.image_url),jsonb_build_object('verified_at',x.checked_at,'source',x.source_url,'image_verified',true,'batch','daily-20261016'),x.checked_at,x.checked_at from batch_input x join shops s on s.shop_name=x.shop
 where not exists(select 1 from products p where p.etsy_listing_id=x.listing_id)
 on conflict(shop_id,etsy_listing_id) do nothing returning id,shop_id,etsy_listing_id
) insert into new_products select * from ins;
insert into content_variants(shop_id,product_id,platform,creative_id,image_url,title,body,destination_url,board_or_category,content_type,status)
select p.shop_id,p.id,'pinterest','verified-original-20261016',x.image_url,x.new_title,x.body,x.source_url,x.category,'product','ready' from new_products p join batch_input x on x.listing_id=p.etsy_listing_id;
insert into content_variants(shop_id,product_id,platform,creative_id,image_url,title,body,destination_url,board_or_category,content_type,status)
select p.shop_id,p.id,'facebook','verified-original-20261016',x.image_url,x.new_title,x.facebook_draft,x.source_url,x.category,'product','draft' from new_products p join batch_input x on x.listing_id=p.etsy_listing_id;
insert into publish_queue(shop_id,product_id,content_variant_id,platform,social_account_id,status)
select p.shop_id,p.id,cv.id,'pinterest',a.id,'ready' from new_products p join batch_input x on x.listing_id=p.etsy_listing_id join content_variants cv on cv.product_id=p.id and cv.platform='pinterest' join social_accounts a on a.handle=x.handle and a.platform='pinterest';
insert into pinterest_publish_reviews(queue_id,board_id,snapshot,listing_checked_at,source_url)
select q.id,x.board_id,pinterest_publish_snapshot(q.id),x.checked_at,x.source_url from new_products p join batch_input x on x.listing_id=p.etsy_listing_id join publish_queue q on q.product_id=p.id and q.platform='pinterest';
select json_build_object('listing_id',p.etsy_listing_id,'queue_id',q.id,'status',q.status,'board_id',r.board_id,'snapshot_matches',r.snapshot=pinterest_publish_snapshot(q.id)) from products p join batch_input x on x.listing_id=p.etsy_listing_id join publish_queue q on q.product_id=p.id and q.platform='pinterest' join pinterest_publish_reviews r on r.queue_id=q.id;
commit;
